    fn parse_layout_ll1(
        &mut self,
        i: u32,
        _failure_context: Option<(SlotId, Option<GssNodeId>)>,
    ) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(115), i));
        if let Some(memo) = self.layout_memo[i as usize] {
            return Some(memo);
        }
        let result = (|| -> Option<SPPFNodeId> {
            let mut j = i;
            let right_child = {
                let start = j;
                let node = self.parse_star_31_ll1(start, Some((SlotId(1155), None)))?;
                let end = self.sppf_node(node).right_extent();
                j = end;
                if let Some(failure) = self.post_conditions(SlotId(1155), start, end) {
                    self.add_failure(end, SlotId(1155), None, failure);
                    return None;
                }
                node
            };
            let left_extent = self.sppf_node(right_child).left_extent();
            let current = right_child;
            Some(self.add_nonterminal_node(NonterminalNode {
                nonterminal_id: NonterminalId(115),
                return_slot: SlotId(1155),
                span: Span {
                    left_extent,
                    right_extent: j,
                },
                child: current,
                ambiguous: false,
            }))
        })();
        if let Some(node) = result {
            self.layout_memo[i as usize] = Some(node);
        }
        result
    }
